mapper.select:
SELECT

FROM ai_team_task t
LEFT JOIN sys_user su ON t.assignee_id = su.user_id
WHERE t.team_id = #{teamId}

    AND t.stage = #{stage}


    AND t.status = #{status}


    AND t.assignee_id = #{assigneeId}

ORDER BY t.status ASC, t.due_at ASC, t.id DESC

mapper.update:
UPDATE ai_team_task
project_id = #{projectId}, stage = #{stage}, title = #{title}, description = #{description}, assignee_id = #{assigneeId}, priority = #{priority}, status = #{status}, due_at = #{dueAt}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
WHERE id = #{id}
